public class QueryDeleteProbe {
    public static List<Database.DeleteResult> erase(String name) {
        return Database.delete([SELECT Id FROM Account WHERE Name = :name WITH SYSTEM_MODE]);
    }
    public static String observe() {
        List<Database.DeleteResult> empty = erase('OwnedDeleteAbsent');
        insert new List<Account>{new Account(Name='OwnedDeleteMany'), new Account(Name='OwnedDeleteMany')};
        List<Database.DeleteResult> many = erase('OwnedDeleteMany');
        insert new Account(Name='OwnedDeleteLimit');
        List<Database.DeleteResult> limited = Database.delete([SELECT Id FROM Account WHERE Name = 'OwnedDeleteLimit' WITH SYSTEM_MODE LIMIT 1]);
        Account scalar = new Account(Name='OwnedDeleteScalar');
        insert scalar;
        Database.DeleteResult single = Database.delete(scalar);
        insert new Account(Name='OwnedDeleteCast');
        Database.DeleteResult casted = Database.delete((Account)[SELECT Id FROM Account WHERE Name = 'OwnedDeleteCast' WITH SYSTEM_MODE LIMIT 1]);
        List<Account> named = new List<Account>{new Account(Name='OwnedDeleteNamed')};
        insert named;
        List<Database.DeleteResult> namedResults = Database.delete(named);
        return 'empty:' + empty.size() + '|many:' + many.size() + ':' + many[0].isSuccess() + ':' + many[1].isSuccess()
            + '|limit:' + limited.size() + ':' + limited[0].isSuccess() + '|scalar:' + single.isSuccess()
            + '|cast:' + casted.isSuccess() + '|named:' + namedResults.size() + ':' + namedResults[0].isSuccess();
    }
}

